+        Cast<bfloat16_t, float, castTraitB322B16>(xBf16, src, preg);
+        DataCopy<bfloat16_t, Reg::StoreDist::DIST_PACK_B32>(((__local_mem__ bfloat16_t*)output + offset), xBf16, preg);
+    } else if constexpr (IsSameType<T, int32_t>::value) {
