+__aicore__ inline uint32_t ROUND_UP32(uint32_t x)
+{
+    if (x % UB_AGLIN_VALUE != 0) {
+        return (x / UB_AGLIN_VALUE + 1) * UB_AGLIN_VALUE;
+    }
+    return x;
+}
